// 高校受験 理科（生物・地学）単元の動く図解スライド（図のなかった単元に1つずつ）。
// 「なぜ？」の連鎖で7枚以上。上に図、下の帯（y=180〜）にそのスライドのひとこと。
import type { DiagramFigure } from './figures';
import { show, bx, lb, ar, ln, ci, pg, sc, flow, stack, dots, cover, band, C, FILL } from './diagram-kit';
import type { DiagramElement } from './figures';

type El = DiagramElement;
const cap = (t: string, color: string = C.ink): El[] => band(180, lb(160, 208, t, 12, color, 'middle', true));
// 前のスライドに描き足す
const S = (note: string, els: El[], c: string, color?: string) => ({ note, add: [...els, ...cap(c, color)] });
// 画面を白紙にして描き直す
const F = (note: string, els: El[], c: string, color?: string) => ({ note, add: [cover(0, 0, 320, 240), ...els, ...cap(c, color)] });
// 染色体（複製されて X 形）と、分かれたあとの 1 本
const XC = (x: number, y: number, c: string = C.purple): El[] => [ln(x - 5, y - 8, x + 5, y + 8, c, false, 4), ln(x - 5, y + 8, x + 5, y - 8, c, false, 4)];
const IC = (x: number, y: number, c: string = C.purple): El[] => [ln(x, y - 8, x, y + 8, c, false, 4)];

