// ───────── 火成岩③：等粒状組織 ─────────
const XT = (x0: number, y0: number, cols: number, rows: number, cw: number, ch: number): El[] => {
  const cl = [FILL.warm, FILL.yellow, FILL.gray, FILL.blue, FILL.green, FILL.red];
  const out: El[] = [];
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const x = x0 + c * cw, y = y0 + r * ch, d = ((r * 3 + c * 5) % 4) - 1.5;
    out.push(pg([[x + d, y], [x + cw - d, y + 1], [x + cw, y + ch + d], [x + 1, y + ch - d]], C.gray, cl[(r + c * 2) % cl.length]));
  }
  return out;
};
