// ───────── 地震による災害と備え ─────────
const WAVE = (x0: number, y0: number, amp: number, n: number, w: number, c: string): El[] => {
  const out: El[] = [];
  for (let i = 0; i < n; i++) out.push(ln(x0 + i * w, y0, x0 + i * w + w / 2, y0 - amp, c, false, 2), ln(x0 + i * w + w / 2, y0 - amp, x0 + (i + 1) * w, y0, c, false, 2));
  return out;
};
